  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (435::BIGINT, 'La profe es muy linda y explica súper claro. Las presentaciones son ordenadas y en general todo es bastante sencillo excepto los exámenes, que son largos y mucho más difíciles que lo visto en clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'e5165f4a7729a63528d54afcd5e764f833ea8dfef997b466d243d5c6386dd03e'::TEXT, ARRAY[1728]::BIGINT[]),
    (435::BIGINT, 'Si asiste pasa relajado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, '33b8f7b79380f23f37e44a1d045a2831598780680953980c5ff4af03f0e8e265'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'con ella se convierte en un curso de habilidades bandas, muy recomendado'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b5d039b963426c7db3b4c47b41456869f12c6585e54fee48d4a1b6d0d606f424'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'Esta profe es de lo mejor de produ. Es super amable y un amor de persona. Ella habla super bien y explica muy claro. Los exámenes son largos y pesados pero califica justo y si le pide ayuda en consulta explica. Está muy guapa también.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '52b98043e47efba41bfce0bcc7da9c0c4c75b48e64fbc36aefaaf1b782f2a5b1'::TEXT, ARRAY[1728]::BIGINT[]),
    (435::BIGINT, 'es súper linda persona, ayuda mucho en consulta y con todo en general, los quices son muy sencillos y también hace trabajos en clase, los exámanes son largos pero ayuda mucho porque son de bastantes puntos, si puede busque exámenes viejos porque se parecen mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'fe6523965cbe2e36cfc1916647ebcc0fa366bc7b1f740f676c6a0ff74bf63bac'::TEXT, ARRAY[1728]::BIGINT[]),
    (435::BIGINT, 'Es buena profesora, los exámenes son muy largos y con mayor dificultad de lo visto en clase. Todo es individual, exceptuando el laboratorio'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2026-06-11T00:00:00+00:00'::TIMESTAMPTZ, '723df0ea83845ccb2def6bf7f1f9b6bd8f7ac9ba52460d3a2c363f2820390024'::TEXT, ARRAY[1728]::BIGINT[]),
    (435::BIGINT, 'El curso es muy bonito, se disfruta mucho. Es un espacio para bajar revoluciones. Se aprende de verdad de los temas del curso. Es MUY estricta con la asistencia por la naturaleza del curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Da crédito extra']::TEXT[], '2026-01-11T00:00:00+00:00'::TIMESTAMPTZ, '4da24776a56e1ad8f5285a9d345b91c09da63c9c227d93446179616b6feb782e'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'Esa clase es una curita para todo el semestre, es muy bonita. La profe la hace muy amena y realmente se aprende lo necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'b83597845c4da97cd7b5fc6b44e49257cba3d494ba99b5d0b670507280db0875'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'Es super bella persona, califica suave y hace bastantes trabajos grupales. Hace que la clase no sea tan pesada y lo motiva a uno a echarle ganas al curso. La materia tiene su dificultad pero con ella es díficil reprobar este curso. Solo pasó lista el primer día de clases.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'f16665c321f3efecbfb6ce96a1f334a43666f41410a7fc416a7c617abb94173c'::TEXT, ARRAY[1728]::BIGINT[]),
    (435::BIGINT, 'La mejor profe para este curso, da muchas herramientas para uno poder empatizar con los demás y desarrollar habilidades blandas, no duda en matricular con ella que da la clase con amor y se preocupa por todos los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '1b9e2e8128ba6138bc8c2b94a1dcdf411de740f8a7f42dd2f500b4d749d65503'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'La profe es demasiado linda y amable, se esfuerza porque los estudiantes se sientan cómodos y hace que el curso sea muy agradable'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'cb82f623a5906d42cd723d9d6cb8f1239aa2554b603e0adb0b0617e1fbb4e0f7'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'La profe explica no muy bien. Días llega normal y otros ni se le puede hablar porque anda amargada. Es desordenada con las evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2024-12-27T00:00:00+00:00'::TIMESTAMPTZ, '3a32c754a2a03b53055fb82020a57cec52e2182b6666a04b156c462547db8a6c'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'El curso es sencillo y muy bonito la verdad. La profe abarca bien la materia, es muy buena gente y le importa que uno de verdad aprenda, es muy comprensiva con las diferentes situaciones que pueda pasarle al estudiante. La profe también cuenta experiencias de ella en clase, es muy provechoso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'c82801bc115ab030858768b137bec4e8ef8c381841371d189963ac5d9cd95c09'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'El curso es muy sin gracia y a la profe le cuesta mucho organizarse, como persona un 100 el curso es fácil pero siento que es una perdida de tiempo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2023-11-14T00:00:00+00:00'::TIMESTAMPTZ, '8694c60a88f023f9cc7f13dee6945df79086e3db5bfcade9cfd5bfe72673bdca'::TEXT, ARRAY[1770]::BIGINT[]),
    (435::BIGINT, 'La profe es un poco desordenada pero en si el curso se pasa yendo a todas las clases. Brinda apoyo ai se le pide'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '69972d22403ab0858029ca3aa50e944545488ad45bf6ba0a0bfef96bfd46b0c0'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'El curso con ella se pasa solo, solo vaya a clases y entregue todo. Las evaluaciones son sencillas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'a1ed53ad3c457c4229bec94ed99c4a96debbceeef57cdd1df820a7e7688011e1'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'Una excelente opción de electiva, se repasan muchos temas importantes, la profe comparte muchas experiencias laborales, las clases en su mayoría son dinámicas y los examenes suelen ser virtuales y en grupo, pero son larguitos, los quices virtuales. Lo único malo es que la profe habla demasiado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '47b71b5ce35ac7da9150c07b27da51159088872d69cfff829007f96e4c6df72b'::TEXT, ARRAY[1770]::BIGINT[]),
    (435::BIGINT, 'Explica súper bien, habla mucho de sus experiencias en el mundo laboral, la clase es cero pesada y muy dinámica. Me gustó bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, '1ce7fc07fd8f24a7f62718dee86a23e76890e53549a3c4217d2adf09b75bdc48'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'La profe es excelente, hace que las clases sean interesantes, hace que el curso no sea complicado y no tan teórico, se aprende con ella y se pasa fácil. Es muy buena gente. La recomiendo para este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, '60fbab04d740f42ce1204a64acdc47a60e21eace787bfb2d78122dbacb7e6616'::TEXT, ARRAY[1751]::BIGINT[]),
    (435::BIGINT, 'Matriculen con ella!! Las clases a veces son larguillas y tiende a salirse un toque del tema, pero ella como persona es un 10/10 y es así con todo, ayuda muchisimo, los ejercicios que deja de practica siempre siempre se parecen al examen o al quiz.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '5514e307ee1dc502df7dfe22702afb2c54409b38fc3e4ac0366bbaa9372a3e65'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'Excelente profe, entre asustado al curso ya que habia esuchado muy malos comentarios sobre todos los demas profes, pero en serio este es la mejor opcion que puede haber entre los profes de este curso, no dude matricular con ella si puede, a veces se desvia un toque pero x, lleva evaluaciones al dia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd191b7c0e57b572dd9397ad73309d31c61d672dcec6396ac5ab00566723d060b'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'Muy buena profe ayuda si el estudiante necesita y si se esfuerza'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '933de70d107a077b6c69f0d703b1a1977f8a3d79a065620f4536c097d06c5863'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'Muy buena profesora, brinda apoyo cuando se le solicita, muy atenta y servicial a la hora de ayudar, muy comida, habla mucho y a veces las clases son un poco largas pero nada más, hace practica en clase que ayuda mucho a la evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '009d5b662fb88966170c785257eb969f605a1005cb31c7b0f29107c4da54ddfe'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'Demasiado desorden, en explicaciones, presentaciones y material que usa.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-03-16T00:00:00+00:00'::TIMESTAMPTZ, '516b8ba50dcbc4bdf1ab22a328d4396a4ea6a0dc5f642d73c42e1a7b81675cea'::TEXT, ARRAY[1719]::BIGINT[]),
    (435::BIGINT, 'Explica muy bien la materia y utiliza ejemplo claros, los examenes son un poco largo pero similares a lo visto en clase nada del otro mundo. Hay trabajos grupales pero son cortos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '84829a95134b8f7e25237d6490f4cb4e807d3b172f7cdb9cb29f23356a1b8638'::TEXT, ARRAY[1728]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
